import {createArtworkBank} from './map4-image-bank.mjs';
import {SHOW_HAZARD_HINTS} from './hazard-presentation.mjs';
// Map4 presentation only: all coordinates, phases and rewards come from the game.
const ROOT=new URL('../assets/map4-city-details-v3/',import.meta.url),NEW_ROOT=new URL('../assets/map4-city-revision-v4/',import.meta.url),EXIT_ROOT=new URL('../assets/map4-city-exit-v7/',import.meta.url),ENTRY_ROOT=new URL('../assets/map4-studio-entry-c-v1/',import.meta.url);
export const PROP_NAMES=Object.freeze(['spike','crusher','emitter','gacha','checkpoint','hatch','crusher-frame','exit-gate']);
const bank=createArtworkBank(new URL('../',import.meta.url),name=>name==='hatch'?new URL('studio-entry-c.png',ENTRY_ROOT).href:name==='exit-gate'?new URL('exit-side.png',EXIT_ROOT).href:new URL(name==='crusher-frame'?name+'.png':'prop-'+name+'.png',name==='crusher-frame'?NEW_ROOT:ROOT).href);
const load=bank.load;
export function cityPropStatus(){return bank.status(PROP_NAMES);}
export const retryCityProps=bank.retry;
const box=(c,x,y,w,h,color)=>{c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));};
function warningMark(r,x,y){if(!SHOW_HAZARD_HINTS)return;const c=r.c;c.save();box(c,x-9,y-21,18,25,'#29272a');c.strokeStyle='#d0b98e';c.lineWidth=1;c.strokeRect(x-9,y-21,18,25);c.fillStyle='#f0d59a';c.font='22px StudioPixel,monospace';c.textAlign='center';c.fillText('!',x,y);c.restore();}
export function drawCitySpikes(r,s,state){const im=load('spike');if(!im)return false;const c=r.c,x=s.x-r.camera;c.save();c.imageSmoothingEnabled=false;box(c,x,589,s.width,7,'#23384c');box(c,x,589,s.width,2,'#7b8b98');for(let dx=5;dx<s.width;dx+=18){box(c,x+dx,591,14,3,'#0f2337');if(state.extension>0)c.drawImage(im,x+dx,590-30*state.extension,14,30*state.extension);}c.restore();return true;}
export function drawCityCrusher(r,q,state,bottom){const im=load('crusher');if(!im)return false;const c=r.c,x=q.x-r.camera;c.save();c.imageSmoothingEnabled=false;const frame=load('crusher-frame');if(frame)c.drawImage(frame,x-14,218,q.width+28,372);else{box(c,x-14,246,q.width+28,22,'#384454');box(c,x-14,246,q.width+28,4,'#aaa194');for(const dx of [-14,q.width+6]){box(c,x+dx,264,8,326,'#394350');box(c,x+dx+2,264,2,322,'#8f9298');}for(const dx of [0,q.width-8]){box(c,x+dx,252,8,8,'#b5996e');box(c,x+dx+2,254,4,4,'#3c3a3e');}}c.drawImage(im,x,bottom-q.height,q.width,q.height);if(state.phase==='warning')warningMark(r,x+q.width/2,210);c.restore();return true;}
export function drawCityEmitter(r,e){const im=load('emitter');if(!im)return false;const c=r.c,x=e.x-r.camera,y=e.y??578;c.save();c.imageSmoothingEnabled=false;c.drawImage(im,18,0,22,32,x-4,y-52,44,64);c.drawImage(im,0,7,19,13,x-40,y-13,38,26);if(e.phase==='telegraph')warningMark(r,x+12,y-62);c.restore();return true;}
export function drawCityProjectile(r,p){const im=load('emitter');if(!im)return false;const c=r.c,x=p.x-r.camera;c.save();c.imageSmoothingEnabled=false;c.drawImage(im,0,12,12,7,x-12,p.y-7,24,14);box(c,x-10,p.y-5,16,10,'#bb805b');box(c,x-9,p.y-3,5,6,'#f2c997');c.restore();return true;}
export function drawCityGacha(r,g){const im=load('gacha');if(!im)return false;const c=r.c,x=g.rules.GACHA.x-r.camera;c.save();c.imageSmoothingEnabled=false;c.drawImage(im,x-58,412,116,178);box(c,x-43,512,70,14,'#1a3044');c.textAlign='center';c.fillStyle=g.map4GachaUsed?'#9fa5a4':'#e8d2a1';c.font='9px monospace';c.fillText(g.map4GachaUsed?'USED':'FREE · 1 PLAY',x-8,522);c.fillStyle='#d6c49e';c.font='10px monospace';c.fillText('LOGIC CODE',x,404);c.textAlign='left';c.restore();return true;}
export function drawCityCheckpoint(r,cp,active){const im=load('checkpoint');if(!im)return false;const c=r.c,x=cp.x-r.camera;if(x<-60||x>r.canvas.width+60)return true;c.save();c.imageSmoothingEnabled=false;c.drawImage(im,x-20,cp.y-114,40,114);r.ellipse(x,cp.y-100,5,5,active?'#d6e8ac':'#526d80');r.ellipse(x,cp.y-92,3,3,active?'#edbd83':'#354b60');if(active)r.glow(x,cp.y-100,55,'#d9eeb62a');box(c,x-13,cp.y-84,26,9,'#233b50');c.fillStyle='#d9d3ba';c.font='10px monospace';c.textAlign='center';c.fillText(cp.id,x,cp.y-77);c.textAlign='left';c.restore();return true;}
export function drawCityHatch(r,g){const im=load('hatch');if(!im)return false;const x=g.rules.SECRET.x-r.camera,c=r.c;if(x+144<0||x-144>r.canvas.width)return true;c.save();c.imageSmoothingEnabled=false;c.drawImage(im,Math.round((x-144)/2)*2,474,288,116);c.restore();return true;}
export function drawCityExit(r,finish){const c=r.c,left=finish.x-r.camera-80,width=672;if(left+width<0||left>r.canvas.width)return true;const im=load('exit-gate');c.save();c.imageSmoothingEnabled=false;if(im)c.drawImage(im,left,590-im.naturalHeight*2,im.naturalWidth*2,im.naturalHeight*2);else{for(const dx of [12,224,436,648]){box(c,left+dx,438,14,152,'#555562');box(c,left+dx+2,438,3,152,'#999083');box(c,left+dx+4,576,14,14,'#3c414d');}box(c,left,402,width,12,'#85818a');box(c,left+16,390,width-16,12,'#494d5e');box(c,left,414,width,24,'#343b4b');for(const dx of [110,330,550])box(c,left+dx,438,16,4,'#c7a673');}const top=im?590-im.naturalHeight*2:402;box(c,left+45,top+32,108,18,'#29272a');c.textAlign='center';c.fillStyle='#f0e3c8';c.font='12px StudioPixel,monospace';c.fillText('港區出口 →',left+99,top+45);c.restore();return true;}
